import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for HardTanh
hardtanh_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void hardtanh_kernel(const float* in, float* out, int size, float min_val, float max_val) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        if (val < min_val) {
            val = min_val;
        } else if (val > max_val) {
            val = max_val;
        }
        out[idx] = val;
    }
}

torch::Tensor hardtanh_cuda(torch::Tensor input, float min_val, float max_val) {
    auto size = input.numel();
    auto out = torch::empty_like(input);
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    hardtanh_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(),
                                               out.data_ptr<float>(),
                                               size,
                                               min_val,
                                               max_val);
    return out;
}
"""

hardtanh_cpp_source = r"""
torch::Tensor hardtanh_cuda(torch::Tensor input, float min_val, float max_val);
"""

# Compile the inline CUDA code for HardTanh
custom_hardtanh = load_inline(
    name="custom_hardtanh",
    cpp_sources=hardtanh_cpp_source,
    cuda_sources=hardtanh_source,
    functions=["hardtanh_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that replaces HardTanh with a custom CUDA implementation.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.custom_hardtanh = custom_hardtanh

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.custom_hardtanh.hardtanh_cuda(x, -1.0, 1.0)

